root.addEventListener("scroll", (event) => {
      if (!(event.target instanceof Element)) return;

      scrolled.add(event.target);
      placing ||= requestAnimationFrame(() => {
        placing = 0;

        for (const [element, { slot }] of entries) {
          if ([...scrolled].some((target) => target.contains(element))) place(element, slot);
        }

        scrolled.clear();
      });
    }, true)

dom.addEventListener("toggle", () => {
              const at = getPos();
              summary.setAttribute("aria-expanded", String(dom.open));

              if (at === undefined || key.getState(view.state)!.has(at - 1) === !dom.open) return;
              view.dispatch(view.state.tr.setMeta(key, { pos: at - 1, folded: !dom.open }));
            })

element.addEventListener("pointerdown", (event) => {
          contextClick = event.button === 0 && event.ctrlKey;

          // macOS Ctrl-click must not focus a row, blur unfinished input or arm its sort sensor.
          if (contextClick) {
            event.preventDefault();
            event.stopPropagation();
          }
        }, true)

element.addEventListener("click", (event) => {
          if (!contextClick && !event.ctrlKey) return;

          contextClick = false;
          event.preventDefault();
          event.stopPropagation();
        }, true)
